export const fragmentShaderSource = `#version 300 es
precision mediump float;

in vec3 v_normal;
in vec2 v_texCoord;
in vec4 v_tangent;

uniform int u_materialID;
uniform lowp sampler2DArray u_albedoTextures;

struct Material {
    vec4 albedoColor;
    vec4 pbrParams;
    ivec4 texIndices;
};

layout(std140) uniform MaterialBlock {
    Material u_materials[16];
};

out vec4 fragColor;

void main() {
    Material mat = u_materials[u_materialID];

    vec4 albedo = mat.albedoColor;
    int albedoLayer = mat.texIndices.x;

    if (albedoLayer >= 0) {
        vec4 texSample = texture(u_albedoTextures, vec3(v_texCoord, float(albedoLayer)));
        albedo *= texSample;
    }

    float roughness = mat.pbrParams.x;
    float metallic  = mat.pbrParams.y;

    vec3 N = normalize(v_normal);
    vec3 L = normalize(vec3(0, 0, 1));
    float NdotL = max(dot(N, L), 0.15);

    fragColor = vec4(albedo.rgb * NdotL, albedo.a);
}`;