import type { RenderConfigs, Backend } from "../renderer";
import { vertexShaderSource } from "../../graphics/shaders/webgl/vertex";
import { fragmentShaderSource } from "../../graphics/shaders/webgl/fragment";
import type { Camera } from "../camera";
import type { MeshData, Mesh } from "../../graphics/mesh";
import { Transform } from "../../math/transform";
import { Matrix4 } from "../../math/matrix";
import { Vector3 } from "../../math/vector3";
import type { Material, MaterialData } from "../../graphics/material";
import type { Texture, TextureData } from "../../graphics/texture";

interface ShaderLocations {
	program: WebGLProgram;
	attributes: {
		position: GLint;
		normal: GLint;
		texCoord: GLint;
		tangent: GLint;
	};
	uniforms: {
		viewProjection: WebGLUniformLocation;
		meshTransform: WebGLUniformLocation;
		normalMatrix: WebGLUniformLocation;
		materialID: WebGLUniformLocation;
		albedoTextures: WebGLUniformLocation;
	};
	uboBlocks: {
		materialBlock: GLuint;
	};
}

export class WebGLBackend implements Backend {
	configs: RenderConfigs;
	private ctx: WebGL2RenderingContext;
	private shaderLocations!: ShaderLocations;

	private tempNormalMatrix = new Float32Array(9);

	private maxMaterials = 16;

	private materialBuffer!: WebGLBuffer;
	private materialBufferData = new Float32Array(this.maxMaterials * 12);
	private materialBufferOffset = 0;

	private albedoTextureArray!: WebGLTexture;
	private textureSize = 1024;
	private nextTextureLayer = 0;

	private bitCastBuffer = new ArrayBuffer(4);
	private bitCastInt32 = new Int32Array(this.bitCastBuffer);
	private bitCastFloat32 = new Float32Array(this.bitCastBuffer);

	constructor(canvas: HTMLCanvasElement, configs: RenderConfigs) {
		this.configs = configs;

		this.ctx = canvas.getContext("webgl2")!;

		this.ctx.enable(this.ctx.CULL_FACE);
		this.ctx.cullFace(this.ctx.BACK);
		this.ctx.frontFace(this.ctx.CCW);
		this.ctx.enable(this.ctx.BLEND);
		this.ctx.blendFunc(this.ctx.SRC_ALPHA, this.ctx.ONE_MINUS_SRC_ALPHA);
		this.ctx.enable(this.ctx.DEPTH_TEST);

		this.initShaderProgram(vertexShaderSource, fragmentShaderSource);
		this.initMaterialSystem();

		this.resize(500, 500);
	}

	private initShaderProgram(
		vertexShaderSource: string,
		fragmentShaderSource: string,
	): void {
		const program = this.ctx.createProgram();

		this.ctx.attachShader(
			program,
			this.loadShader(this.ctx.VERTEX_SHADER, vertexShaderSource),
		);
		this.ctx.attachShader(
			program,
			this.loadShader(this.ctx.FRAGMENT_SHADER, fragmentShaderSource),
		);

		this.ctx.linkProgram(program);

		this.shaderLocations = {
			program: program,

			attributes: {
				position: this.ctx.getAttribLocation(program, "a_position"),
				normal: this.ctx.getAttribLocation(program, "a_normal"),
				texCoord: this.ctx.getAttribLocation(program, "a_texCoord"),
				tangent: this.ctx.getAttribLocation(program, "a_tangent")
			},

			uniforms: {
				viewProjection: this.ctx.getUniformLocation(
					program,
					"u_viewProjection",
				)!,
				meshTransform: this.ctx.getUniformLocation(program, "u_meshTransform")!,
				normalMatrix: this.ctx.getUniformLocation(program, "u_normalMatrix")!,
				materialID: this.ctx.getUniformLocation(program, "u_materialID")!,
				albedoTextures: this.ctx.getUniformLocation(
					program,
					"u_albedoTextures",
				)!,
			},

			uboBlocks: {
				materialBlock: this.ctx.getUniformBlockIndex(program, "MaterialBlock"),
			},
		};

		this.ctx.useProgram(program);

		if (this.shaderLocations.uniforms.albedoTextures !== null) {
			this.ctx.uniform1i(this.shaderLocations.uniforms.albedoTextures, 0);
		}
	}

	private loadShader(type: GLenum, source: string): WebGLShader {
		const shader = this.ctx.createShader(type) as WebGLShader;

		this.ctx.shaderSource(shader, source);
		this.ctx.compileShader(shader);

		if (!this.ctx.getShaderParameter(shader, this.ctx.COMPILE_STATUS)) {
			console.error("" + this.ctx.getShaderInfoLog(shader));
		}

		return shader;
	}

	private initMaterialSystem(): void {
		this.albedoTextureArray = this.ctx.createTexture()!;
		this.ctx.bindTexture(this.ctx.TEXTURE_2D_ARRAY, this.albedoTextureArray);

		const mipLevels = Math.floor(Math.log2(this.textureSize)) + 1;
		this.ctx.texStorage3D(
			this.ctx.TEXTURE_2D_ARRAY,
			mipLevels,
			this.ctx.RGBA8,
			this.textureSize,
			this.textureSize,
			this.maxMaterials,
		);

		this.ctx.texParameteri(
			this.ctx.TEXTURE_2D_ARRAY,
			this.ctx.TEXTURE_MIN_FILTER,
			this.ctx.LINEAR,
		);
		this.ctx.texParameteri(
			this.ctx.TEXTURE_2D_ARRAY,
			this.ctx.TEXTURE_MAG_FILTER,
			this.ctx.LINEAR,
		);

		this.ctx.activeTexture(this.ctx.TEXTURE0);
		this.ctx.bindTexture(this.ctx.TEXTURE_2D_ARRAY, this.albedoTextureArray);

		this.materialBuffer = this.ctx.createBuffer()!;
		this.ctx.bindBuffer(this.ctx.UNIFORM_BUFFER, this.materialBuffer);
		this.ctx.bufferData(
			this.ctx.UNIFORM_BUFFER,
			this.materialBufferData.byteLength,
			this.ctx.DYNAMIC_DRAW,
		);

		const bindingPoint = 0;
		this.ctx.uniformBlockBinding(
			this.shaderLocations.program,
			this.shaderLocations.uboBlocks.materialBlock,
			bindingPoint,
		);
		this.ctx.bindBufferBase(
			this.ctx.UNIFORM_BUFFER,
			bindingPoint,
			this.materialBuffer,
		);
	}

	private intToFloatBits(val: number): number {
		this.bitCastInt32[0] = val;
		return this.bitCastFloat32[0]!;
	}


	// ---------------------------------------------------------------------


	public createTexture(data: TextureData): Texture {
		const layerIndex = this.nextTextureLayer++;

		const canvas = document.createElement("canvas");
		canvas.width = this.textureSize;
		canvas.height = this.textureSize;

		const ctx = canvas.getContext("2d")!;
		ctx.drawImage(data.source, 0, 0, this.textureSize, this.textureSize);

		this.ctx.bindTexture(this.ctx.TEXTURE_2D_ARRAY, this.albedoTextureArray);
		this.ctx.texSubImage3D(
			this.ctx.TEXTURE_2D_ARRAY,
			0,
			0,
			0,
			layerIndex,
			this.textureSize,
			this.textureSize,
			1,
			this.ctx.RGBA,
			this.ctx.UNSIGNED_BYTE,
			canvas
		);
		this.ctx.generateMipmap(this.ctx.TEXTURE_2D_ARRAY);

		return { textureID: layerIndex };
	}

	public createMaterial(data: MaterialData): Material {
		const materialIndex = this.materialBufferOffset / 12;

		const albedo = data.albedo ?? [1.0, 1.0, 1.0, 1.0];
		const roughness = data.roughness ?? 0.5;
		const metallic = data.metallic ?? 0.0;
		const ao = data.ambientOcclusion ?? 1.0;

		const startOffset = this.materialBufferOffset;

		this.materialBufferData[this.materialBufferOffset++] = albedo[0];
		this.materialBufferData[this.materialBufferOffset++] = albedo[1];
		this.materialBufferData[this.materialBufferOffset++] = albedo[2];
		this.materialBufferData[this.materialBufferOffset++] = albedo[3];

		this.materialBufferData[this.materialBufferOffset++] = roughness;
		this.materialBufferData[this.materialBufferOffset++] = metallic;
		this.materialBufferData[this.materialBufferOffset++] = ao;
		this.materialBufferData[this.materialBufferOffset++] = 0.0;

		this.materialBufferData[this.materialBufferOffset++] = this.intToFloatBits(data.albedoTexture?.textureID ?? -1);
		this.materialBufferData[this.materialBufferOffset++] = this.intToFloatBits(data.normalTexture?.textureID ?? -1);
		this.materialBufferData[this.materialBufferOffset++] = this.intToFloatBits(data.ormTexture?.textureID ?? -1);
		this.materialBufferData[this.materialBufferOffset++] = this.intToFloatBits(-1);

		this.ctx.bindBuffer(this.ctx.UNIFORM_BUFFER, this.materialBuffer);
		this.ctx.bufferSubData(
			this.ctx.UNIFORM_BUFFER,
			startOffset * Float32Array.BYTES_PER_ELEMENT,
			this.materialBufferData.subarray(startOffset, this.materialBufferOffset),
		);

		return { materialID: materialIndex };
	}


	// ---------------------------------------------------------------------


	private createVertexData(data: MeshData): {
		vertexData: Float32Array;
		floatsPerVert: number;
	} {
		const vertexCount = data.positions.length / 3;
		const hasNormals = data.normals !== undefined && data.normals.length > 0;
		const hasUVs = data.uvs !== undefined && data.uvs.length > 0;
		const hasTangents = data.tangents !== undefined && data.tangents.length > 0;

		let floatsPerVert = 3;
		if (hasNormals) floatsPerVert += 3;
		if (hasUVs) floatsPerVert += 2;
		if (hasTangents) floatsPerVert += 4;

		const vertexData = new Float32Array(vertexCount * floatsPerVert);

		const positions = data.positions;
		const normals = hasNormals ? data.normals : undefined;
		const uvs = hasUVs ? data.uvs : undefined;
		const tangents = hasTangents ? data.tangents : undefined;

		let offset = 0;
		for (let i = 0; i < vertexCount; i++) {
			vertexData[offset++] = positions[i * 3]!;
			vertexData[offset++] = positions[i * 3 + 1]!;
			vertexData[offset++] = positions[i * 3 + 2]!;

			if (normals) {
				vertexData[offset++] = normals[i * 3]!;
				vertexData[offset++] = normals[i * 3 + 1]!;
				vertexData[offset++] = normals[i * 3 + 2]!;
			}

			if (uvs) {
				vertexData[offset++] = uvs[i * 2]!;
				vertexData[offset++] = uvs[i * 2 + 1]!;
			}

			if (tangents) {
				vertexData[offset++] = tangents[i * 4]!;
				vertexData[offset++] = tangents[i * 4 + 1]!;
				vertexData[offset++] = tangents[i * 4 + 2]!;
				vertexData[offset++] = tangents[i * 4 + 3]!;
			}
		}

		return { vertexData, floatsPerVert };
	}

	public createMesh(data: MeshData): Mesh {
		const { vertexData, floatsPerVert } = this.createVertexData(data);

		const drawType = this.ctx.DYNAMIC_DRAW;
		//const drawType = this.ctx.STATIC_DRAW;

		const vao = this.ctx.createVertexArray()!;
		this.ctx.bindVertexArray(vao);

		const vbo = this.ctx.createBuffer()!;
		this.ctx.bindBuffer(this.ctx.ARRAY_BUFFER, vbo);
		this.ctx.bufferData(this.ctx.ARRAY_BUFFER, vertexData, drawType);

		const ebo = this.ctx.createBuffer()!;
		this.ctx.bindBuffer(this.ctx.ELEMENT_ARRAY_BUFFER, ebo);
		this.ctx.bufferData(this.ctx.ELEMENT_ARRAY_BUFFER, data.indices, drawType);

		const stride = floatsPerVert * Float32Array.BYTES_PER_ELEMENT;
		let offset = 0;

		this.ctx.enableVertexAttribArray(this.shaderLocations.attributes.position);
		this.ctx.vertexAttribPointer(
			this.shaderLocations.attributes.position,
			3,
			this.ctx.FLOAT,
			false,
			stride,
			offset,
		);
		offset += 3 * Float32Array.BYTES_PER_ELEMENT;

		const hasNormals = data.normals !== undefined && data.normals.length > 0;
		if (hasNormals) {
			this.ctx.enableVertexAttribArray(this.shaderLocations.attributes.normal);
			this.ctx.vertexAttribPointer(
				this.shaderLocations.attributes.normal,
				3,
				this.ctx.FLOAT,
				false,
				stride,
				offset,
			);
			offset += 3 * Float32Array.BYTES_PER_ELEMENT;
		}

		const hasUVs = data.uvs !== undefined && data.uvs.length > 0;
		if (hasUVs) {
			this.ctx.enableVertexAttribArray(
				this.shaderLocations.attributes.texCoord,
			);
			this.ctx.vertexAttribPointer(
				this.shaderLocations.attributes.texCoord,
				2,
				this.ctx.FLOAT,
				false,
				stride,
				offset,
			); offset += 2 * Float32Array.BYTES_PER_ELEMENT;
		}

		const hasTangents = data.tangents !== undefined && data.tangents.length > 0;
		if (hasTangents) {
			if (this.shaderLocations.attributes.tangent !== undefined &&
				this.shaderLocations.attributes.tangent !== -1) {
				this.ctx.enableVertexAttribArray(this.shaderLocations.attributes.tangent);
				this.ctx.vertexAttribPointer(
					this.shaderLocations.attributes.tangent,
					4,
					this.ctx.FLOAT,
					false,
					stride,
					offset
				);
			}
		}

		this.ctx.bindVertexArray(null);

		const indexType =
			data.indices instanceof Uint16Array
				? this.ctx.UNSIGNED_SHORT
				: this.ctx.UNSIGNED_INT;

		return {
			vao,
			vbo,
			ebo,
			indexCount: data.indices.length,
			indexType,
		};
	}

	public updateMesh(mesh: Mesh, data: MeshData): void {
		const { vertexData, floatsPerVert } = this.createVertexData(data);

		this.ctx.bindBuffer(this.ctx.ARRAY_BUFFER, mesh.vbo);
		this.ctx.bufferSubData(this.ctx.ARRAY_BUFFER, 0, vertexData);
		this.ctx.bindBuffer(this.ctx.ARRAY_BUFFER, null);

		this.ctx.bindBuffer(this.ctx.ELEMENT_ARRAY_BUFFER, mesh.ebo);
		this.ctx.bufferSubData(this.ctx.ELEMENT_ARRAY_BUFFER, 0, data.indices);

		mesh.indexCount = data.indices.length;
		mesh.indexType =
			data.indices instanceof Uint16Array
				? this.ctx.UNSIGNED_SHORT
				: this.ctx.UNSIGNED_INT;
	}

	public drawMesh(mesh: Mesh, material: Material, transformMatrix: Matrix4): void {
		const gl = this.ctx;

		gl.bindVertexArray(mesh.vao);

		gl.uniformMatrix4fv(
			this.shaderLocations.uniforms.meshTransform,
			false,
			transformMatrix.data,
		);

		const normalMatrixData = Matrix4.normalMatrix(
			transformMatrix,
			this.tempNormalMatrix,
		);
		gl.uniformMatrix3fv(
			this.shaderLocations.uniforms.normalMatrix,
			false,
			normalMatrixData,
		);

		gl.uniform1i(
			this.shaderLocations.uniforms.materialID,
			material.materialID,
		);

		gl.drawElements(
			gl.TRIANGLES,
			mesh.indexCount,
			mesh.indexType,
			0,
		);

		gl.bindVertexArray(null);
	}


	// ---------------------------------------------------------------------


	public clear(r: number, g: number, b: number, a: number): void {
		this.ctx.clearColor(r / 255, g / 255, b / 255, a);
		this.ctx.clear(this.ctx.COLOR_BUFFER_BIT | this.ctx.DEPTH_BUFFER_BIT);
	}

	public updateView(camera: Camera): void {
		this.ctx.uniformMatrix4fv(
			this.shaderLocations.uniforms.viewProjection,
			false,
			camera.viewProjectionMatrix.data,
		);
	}

	public resize(width: number, height: number): void {
		this.ctx.viewport(0, 0, width, height);
	}
}
