import { MeshBuilder } from "./graphics/mesh";
import { OrthographicCamera, PerspectiveCamera } from "./core/camera";
import { Engine } from "./core/engine";
import { Backends } from "./core/renderer";
import { Transform } from "./math/transform";
import { Vector3 } from "./math/vector3";
import { Quaternion } from "./math/quaternion";
import { MaterialBuilder } from "./graphics/material";
import { TextureBuilder } from "./graphics/texture";

const canvas = document.createElement("canvas");
document.body.appendChild(canvas);

const engine = new Engine(canvas, { backend: Backends.WEBGL });

const myMesh = engine.createMesh(MeshBuilder.Box(1, 1, 1));
const myTransform = new Transform(new Vector3(0, 0, -3));
const myTexture = engine.createTexture(await TextureBuilder.fromURL("https://png.pngtree.com/background/20250218/original/pngtree-vibrant-background-design-abstract-paint-fluid-texture-bursting-with-bright-colors-picture-image_15274766.jpg"));
const myMaterial = engine.createMaterial(
    MaterialBuilder.create({ albedo: [0, 1, 1, 1], albedoTexture: myTexture})
);

engine.start();

window.addEventListener("resize", () => {
	engine.resize(window.innerWidth, window.innerHeight);
});

engine.resize(window.innerWidth, window.innerHeight);

const cam = new PerspectiveCamera();

engine.setCamera(cam);

engine.onFrame = (renderer, timestamp, delta) => {
	renderer.clear(0, 0, 0, 1);

	//myTransform.setPosition(Math.sin(timestamp / 200) * 3, 0, -7);
	//myTransform.setScale(new Vector3(1, 1, 1));
	myTransform.setRotation(Quaternion.fromAxisAngle(new Vector3(Math.sin(timestamp / 1000), Math.sin(timestamp / 2000), Math.sin(timestamp / 3000)), timestamp / 1000));

	renderer.drawMesh(myMesh, myMaterial, myTransform);

	// renderer.drawCircle(-2, -2, 1, -10);
	// renderer.drawTriangle(
	// 	2,
	// 	Math.sin(timestamp / 2000) * 2 + 1,
	// 	-0.5,
	// 	Math.sin(timestamp / 2000) + 1,
	// 	Math.sin(timestamp / 2000),
	// 	-1,
	// 	-10,
	// );
};
